args.command:
cat > /tmp/harness/bin/git <<'EOF'
#!/bin/bash
# Mode-controlled logging git wrapper.
# /tmp/harness/mode contents control behavior; modes:
#   passthrough (default), fail-log:N (exit N on log), fail-revlist:N,
#   garbage-log (invalid utf8 on log stdout), garbage-revlist, empty-revlist,
#   multiline-revlist, describe-out:<string file> (print file contents for describe, exit ok)
{
  printf 'PWD=%q' "$PWD"
  for a in "$@"; do printf ' ARG=%q' "$a"; done
  printf ' GIT_DIR_ENV=%q GIT_WORK_TREE_ENV=%q\n' "${GIT_DIR-UNSET}" "${GIT_WORK_TREE_ENV-UNSET}"
} >> /tmp/harness/gitlog
MODE=$(cat /tmp/harness/mode 2>/dev/null || echo passthrough)
sub=""
for a in "$@"; do case "$a" in log|rev-list|describe) sub="$a"; break;; esac; done
case "$MODE" in
  passthrough) exec /usr/bin/git "$@" ;;
  fail-log:*) [ "$sub" = log ] && { echo "simulated failure" >&2; exit "${MODE#fail-log:}"; } ;;
  fail-revlist:*) [ "$sub" = rev-list ] && { echo "simulated failure" >&2; exit "${MODE#fail-revlist:}"; } ;;
  garbage-log) [ "$sub" = log ] && { printf '\xff\xfe\x00garbage\xff'; exit 0; } ;;
  garbage-log-nonzero) [ "$sub" = log ] && { printf '\xff\xfegarbage'; exit 1; } ;;
  garbage-revlist) [ "$sub" = rev-list ] && { printf '\xff\xfenothex\n'; exit 0; } ;;
  empty-revlist) [ "$sub" = rev-list ] && exit 0 ;;
  multiline-revlist) [ "$sub" = rev-list ] && { printf 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\nbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\n'; exit 0; } ;;
  revlist-trailing-junk) [ "$sub" = rev-list ] && { printf 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa extra junk\n'; exit 0; } ;;
  describe-out:*) [ "$sub" = describe ] && { cat "${MODE#describe-out:}"; exit 0; } ;;
  describe-fail:*) [ "$sub" = describe ] && { echo "no tags" >&2; exit "${MODE#describe-fail:}"; } ;;
esac
exec /usr/bin/git "$@"
EOF
chmod +x /tmp/harness/bin/git
cd /tmp/proj
export PATH=/tmp/harness/bin:$PATH
printf '1.0.0\n' > /tmp/harness/d_nl
printf '1.0.0' > /tmp/harness/d_nonl
printf '1.0.0-rc.1\n' > /tmp/harness/d_rc
printf 'v1.0.0\n' > /tmp/harness/d_v
run() { echo "=== $1 ==="; shift; rm -f /tmp/harness/gitlog; /workspace/executable "$@" >/tmp/harness/out 2>/tmp/harness/err; echo "EXIT=$?"; head -3 /tmp/harness/out; echo "--STDERR--"; cat /tmp/harness/err; }
echo describe-out:/tmp/harness/d_nl > /tmp/harness/mode; run "-M describe=1.0.0+NL" -M
echo describe-out:/tmp/harness/d_nonl > /tmp/harness/mode; run "-M describe=1.0.0-noNL" -M
echo describe-out:/tmp/harness/d_v > /tmp/harness/mode; run "-M describe=v1.0.0+NL" -M
echo describe-out:/tmp/harness/d_rc > /tmp/harness/mode; run "-M describe=1.0.0-rc.1" -M
echo describe-out:/tmp/harness/d_nonl > /tmp/harness/mode; run "-m no-NL" -m; run "-p no-NL" -p
echo describe-fail:128 > /tmp/harness/mode; run "-M describe exit 128" -M
echo describe-fail:1 > /tmp/harness/mode; run "-M describe exit 1" -M
